/// Where the volume came from. Required.
func (rcv *AGV) PROVENANCE(obj *AGVProvenance) *AGVProvenance {
	o := flatbuffers.UOffsetT(rcv._tab.Offset(68))
	if o != 0 {
		x := rcv._tab.Indirect(o + rcv._tab.Pos)
		if obj == nil {
			obj = new(AGVProvenance)
		}
		obj.Init(rcv._tab.Bytes, x)
		return obj
	}
	return nil
}

func (rcv *AGV) Provenance(obj *AGVProvenance) *AGVProvenance {
	return rcv.PROVENANCE(obj)
}

